namespace iot {

class CircuitBreaker {
public:
    enum State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int threshold = 5, int timeout_ms = 30000)
        : failure_count_(0), threshold_(threshold),
          timeout_ms_(timeout_ms), state_(CLOSED) {}

    State get_state() const { return state_; }

    bool allow_request() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (state_ == OPEN) {
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_failure_time_).count();
            if (elapsed > timeout_ms_) {
                state_ = HALF_OPEN;
                return true;
            }
            return false;
        }
        return true;
    }

    void record_success() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_ = 0;
        state_ = CLOSED;
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mtx_);
        failure_count_++;
        last_failure_time_ = std::chrono::steady_clock::now();
        if (failure_count_ >= threshold_) {
            state_ = OPEN;
        }
    }

private:
    int failure_count_;
    int threshold_;
    int timeout_ms_;
    State state_;
    std::mutex mtx_;
    std::chrono::steady_clock::time_point last_failure_time_;
};

class PathNormalizer {
public:
    static std::string normalize(const std::string& path) {
        std::vector<std::string> components;
        std::istringstream stream(path);
        std::string segment;

        while (std::getline(stream, segment, '/')) {
            if (segment == ".." && !components.empty()) {
                components.pop_back();
            } else if (segment != "." && segment != "" && segment != "..") {
                components.push_back(segment);
            }
        }

        std::string result;
        for (const auto& comp : components) {
            result += "/" + comp;
        }
        return result.empty() ? "/" : result;
    }

    static std::string decode_uri_component(const std::string& encoded) {
        std::string decoded;
        for (size_t i = 0; i < encoded.size(); i++) {
            if (encoded[i] == '%' && i + 2 < encoded.size()) {
                char hex[3] = { encoded[i+1], encoded[i+2], '\0' };
                decoded += static_cast<char>(strtol(hex, nullptr, 16));
                i += 2;
            } else {
                decoded += encoded[i];
            }
        }
        return decoded;
    }
};

class FirmwareFileService {
public:
    FirmwareFileService(const std::string& base_dir)
        : base_dir_(base_dir), breaker_(3, 10000) {}

    std::string read_config(const std::string& requested_path) {
        if (!breaker_.allow_request()) {
            return "{\"error\": \"service unavailable\"}";
        }

        std::string safe_path = sanitize_path(requested_path);

        std::string full_path = base_dir_ + safe_path;

        std::ifstream file(full_path);
        if (!file.is_open()) {
            breaker_.record_failure();
            return "{\"error\": \"not found\"}";
        }

        breaker_.record_success();
        std::stringstream buffer;
        buffer << file.rdbuf();
        return buffer.str();
    }

private:
    std::string sanitize_path(const std::string& input) {
        // First decode any URL encoding
        std::string decoded = PathNormalizer::decode_uri_component(input);

        // Normalize path to remove traversal sequences
        std::string normalized = PathNormalizer::normalize(decoded);

        // Verify the path stays within allowed directory
        if (!is_within_base(normalized)) {
            return "/default.conf";
        }

        return normalized;
    }

    bool is_within_base(const std::string& path) {
        // Resolve the canonical form and check prefix
        std::string full = base_dir_ + path;

        // Check that after normalization, path doesn't escape
        // We verify the normalized path starts with base_dir_
        char resolved[4096];
        char base_resolved[4096];

        // On embedded systems, realpath may not resolve symlinks
        // Use string prefix check on normalized path
        strncpy(resolved, full.c_str(), sizeof(resolved) - 1);
        resolved[sizeof(resolved) - 1] = '\0';
        strncpy(base_resolved, base_dir_.c_str(), sizeof(base_resolved) - 1);
        base_resolved[sizeof(base_resolved) - 1] = '\0';

        // Normalize both for comparison
        std::string norm_full = PathNormalizer::normalize(std::string(resolved));
        std::string norm_base = PathNormalizer::normalize(std::string(base_resolved));

        return norm_full.find(norm_base) == 0;
    }

    std::string base_dir_;
    CircuitBreaker breaker_;
};

} // namespace iot

// Entry point for HTTP request handler
extern "C" const char* handle_file_request(const char* base, const char* path) {
    static std::string result;
    iot::FirmwareFileService service(base);
    result = service.read_config(path);
    return result.c_str();
}
